from __future__ import annotations
import os
import sys
from collections.abc import Sequence
from re import Pattern
from astroid import modutils
from pylint.typing import ErrorDescriptionDict, ModuleDescriptionDict


def _is_in_ignore_list_re(element: str, ignore_list_re: list[Pattern[str]]) -> bool:
    """Determines if the element is matched in a regex ignore-list."""
    return any(file_pattern.match(element) for file_pattern in ignore_list_re)


def _is_ignored_file(
    element: str,
    ignore_list: list[str],
    ignore_list_re: list[Pattern[str]],
    ignore_list_paths_re: list[Pattern[str]],
) -> bool:
    basename = os.path.basename(element)
    full_path = os.path.abspath(element)
    return (
        basename in ignore_list
        or _is_in_ignore_list_re(basename, ignore_list_re)
        or _is_in_ignore_list_re(full_path, ignore_list_paths_re)
    )


def _should_ignore_path(path: str, ignore_paths: list[str]) -> bool:
    """Check if the given path should be ignored based on the ignore-paths configuration."""
    return any(path.startswith(ignore_path) for ignore_path in ignore_paths)


def expand_modules(
    modules: Sequence[str],
    ignore_list: list[str],
    ignore_list_re: list[Pattern[str]],
    ignore_list_paths_re: list[Pattern[str]],
    ignore_paths: list[str],
    recursive: bool = False,
) -> tuple[list[ModuleDescriptionDict], list[ErrorDescriptionDict]]:
    expanded_modules = []
    errors = []
    for module in modules:
        if _is_ignored_file(module, ignore_list, ignore_list_re, ignore_list_paths_re):
            continue
        if recursive and os.path.isdir(module):
            for root, _, files in os.walk(module):
                for file in files:
                    full_path = os.path.join(root, file)
                    if _is_ignored_file(full_path, ignore_list, ignore_list_re, ignore_list_paths_re) or _should_ignore_path(full_path, ignore_paths):
                        continue
                    try:
                        expanded_modules.append(modutils.file_info(full_path))
                    except Exception as exc:
                        errors.append({'path': full_path, 'message': str(exc)})
        else:
            try:
                expanded_modules.append(modutils.file_info(module))
            except Exception as exc:
                errors.append({'path': module, 'message': str(exc)})
    return expanded_modules, errors

